body.query:
query ordersQuery($first: Int, $after: String, $query: String!) {
  orders(first: $first, after: $after, query: $query) {
    edges {
      node {
        id
        _id
        name
        total
        fulfillment_status
        financial_status
        customer {
          full_name
          id
        }
        cancelled_at
        date: created_at
        formattedDate: created_at(format: "LLL")
        test
        currency
        checkout {
          id
          store {
            id
            name
          }
          funnel {
            id
            name
          }
        }
        tags
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      startCursor
    }
  }
}
